def label_existing_lines(apps, schema_editor):
    """The first line of every existing quote and invoice bills the cession; the others stay
    « autre ». queryset.update never goes through DocumentLine.save, so issued documents are
    not touched by their own immutability guard (and their stored PDF does not change)."""
    DocumentLine = apps.get_model("documents", "DocumentLine")
    for parent in ("invoice", "quote"):
        first_ids = []
        seen = set()
        lines = (
            DocumentLine.objects.filter(**{f"{parent}__isnull": False})
            .order_by(f"{parent}_id", "position", "id")
            .values_list("id", f"{parent}_id")
        )
        for line_id, parent_id in lines:
            if parent_id not in seen:
                seen.add(parent_id)
                first_ids.append(line_id)
        DocumentLine.objects.filter(id__in=first_ids).update(kind="cession")


